const now = new Date();
const caracasOffset = -4 * 60;
const localNow = new Date(now.getTime() + (now.getTimezoneOffset() + caracasOffset) * 60000);

const targetDate = new Date(localNow.getTime());
targetDate.setDate(targetDate.getDate() + 4);

const pad = (n) => String(n).padStart(2, '0');
const targetStr = `${targetDate.getFullYear()}-${pad(targetDate.getMonth() + 1)}-${pad(targetDate.getDate())}`;

const getField = (obj, regex) => {
  if (!obj) return '';
  for (const k of Object.keys(obj)) {
    if (regex.test(k)) {
      const v = obj[k];
      if (v !== undefined && v !== null) return v;
    }
  }
  return '';
};

const getAmount = (obj) => {
  if (!obj) return 0;
  for (const k of Object.keys(obj)) {
    if (/monto|amount/i.test(k)) {
      const v = obj[k];
      if (v !== undefined && v !== null && v !== '') {
        const n = parseFloat(String(v).replace(/[^0-9.]/g, ''));
        if (!isNaN(n) && n > 0) return n;
      }
    }
  }
  return 0;
};

const normalizeDate = (val) => {
  if (!val) return '';
  const raw = String(val).trim().split(' ')[0].split('T')[0];
  const p = raw.split(/[\/\-]/);
  if (p.length === 3) {
    return p[0].length === 4
      ? `${p[0]}-${pad(p[1])}-${pad(p[2])}`
      : `${p[2].length === 2 ? '20' + p[2] : p[2]}-${pad(p[1])}-${pad(p[0])}`;
  }
  return raw;
};

const results = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const row = items[i].json;
  const rawVence = getField(row, /^vence/i);
  const venceIso = normalizeDate(rawVence);
  const play = String(getField(row, /^play/i)).trim();
  const email = String(getField(row, /^email/i)).trim();
  const usuario = String(getField(row, /^usuario/i)).trim();

  if (venceIso === targetStr && play !== 'SENT4' && usuario !== '') {
    const numAmount = getAmount(row) || 20;
    const cleanAmount = numAmount.toFixed(2);
    const cryptoNum = Number((numAmount * 0.8).toFixed(2));
    const cryptoAmount = cryptoNum.toFixed(2);
    const nombre = String(getField(row, /^nombre/i) || 'Customer').trim();
    const pagaPor = String(getField(row, /^paga/i)).trim().toLowerCase();
    const telefono = String(getField(row, /^tel|phone/i)).replace(/\D/g, '');

    let dateFormatted = 'soon';
    try {
      const parts = venceIso.split('-');
      const d = new Date(parts[0], parts[1] - 1, parts[2]);
      dateFormatted = d.toLocaleDateString('en-US', { month: 'long', day: 'numeric' });
    } catch (e) {
      dateFormatted = venceIso;
    }

    results.push({
      json: {
        ...row,
        row_number: i + 2,
        Nombre: nombre,
        Email: email,
        Usuario: usuario,
        Telefono: telefono,
        Vence: venceIso,
        vence_formatted: dateFormatted,
        Ultimo_Monto: cleanAmount,
        Crypto_Monto: cryptoAmount,
        crypto_num: cryptoNum,
        is_zelle: (pagaPor === 'zelle'),
        checkout_url: 'http://totaltvusa.com/'
      }
    });
  }
}

return results;

const originalItems = $('If es link o zelle?').all(1);
const apiResponses = $input.all();

return originalItems.map((item, index) => {
  const invoiceUrl = apiResponses[index]?.json?.invoice_url || 'http://totaltvusa.com/';
  return {
    json: {
      ...item.json,
      checkout_url: invoiceUrl
    }
  };
});
